// Finite source projection from the reviewed R4 preservation correction to R3.
// This is test evidence only; never a runtime source authority or SQL receipt.
import assert from 'node:assert/strict';import{createHash}from'node:crypto';
export const NOELIA_FISCAL160_SOURCE_CUSTODY=Object.freeze({"version":"noelia-fiscal160-reviewed-r3-r4-source-custody.v1","sealedPredecessorSha256":"824971e4e9924c548b478cefd544d0863535002806d12edd93c45f95bbf8ebf2","publicPredecessorSha256":"2e82695ae2907d4d8e546897e152f4f80142dfed66adb176a55737e62925fd3a","publicSuccessorSha256":"f599ad90489639308a9b5c33c7d6f296a3d65915a16eb07cc83717dcff8ab705","before":" // Finite scope correction to each public160 preservation snapshot only.\n // Without this predicate relocation the13 new QA functions were counted as\n // foreign functions; the unchanged equality correctly rejected R1 before COMMIT.\n const publicPredicate=\"AND NOT(s.nspname='public' AND p.proname LIKE 'own_fiscal_facts_%')\",localPredicate=\"AND NOT(s.nspname=\"+q(schema)+\" AND p.proname LIKE 'own_fiscal_facts_%')\";\n const localizedPreservation=value=>{assert.equal(value.split(publicPredicate).length,2,'NOELIA_FISCAL160_PRESERVATION_SCOPE_ANCHOR');const scoped=value.replace(publicPredicate,()=>localPredicate);assert.equal(scoped.replace(localPredicate,()=>publicPredicate),value,'NOELIA_FISCAL160_PRESERVATION_SCOPE_INVERSE');return normalize(scoped);};\n const before=localizedPreservation(published.before),after=localizedPreservation(published.after),compare=normalize(published.conservation)","after":" const before=normalize(published.before),after=normalize(published.after),compare=normalize(published.conservation)","scope":"complete reviewed source projection; not an installation or native admission"});
export function noeliaFiscal160R3SourceForTest(source){const p=NOELIA_FISCAL160_SOURCE_CUSTODY,hash=v=>createHash('sha256').update(v).digest('hex');assert.equal(typeof source,'string');assert.equal(hash(source),p.publicSuccessorSha256,'NOELIA_FISCAL160_REVIEWED_R4_SOURCE_REQUIRED');assert.equal(source.split(p.before).length,2,'NOELIA_FISCAL160_ONE_SCOPE_CORRECTION_REQUIRED');const prior=source.replace(p.before,()=>p.after);assert.equal(hash(prior),p.publicPredecessorSha256,'NOELIA_FISCAL160_COMPLETE_R3_SOURCE_INVERSE');assert.equal(prior.split(p.after).length,2);assert.equal(prior.replace(p.after,()=>p.before),source,'NOELIA_FISCAL160_COMPLETE_FORWARD_ROUNDTRIP');return prior;}
